sys_script_include.script:
/**
 * NetraTools — server-side GlideRecord operations.
 *
 * v3 adds:
 *   - Approvals: list, approve, reject
 *   - Watchlist: add/remove a ticket to the user's watch list
 *   - Search:    free-text incident search
 *   - Read:      fetch full record + comments for read-aloud
 *
 * Tables referenced via x_196061_netra_v1 placeholder, replaced at install.
 */
var NetraTools = Class.create();
NetraTools.prototype = {

    STATE:        { NEW: '1', IN_PROGRESS: '2', ON_HOLD: '3', RESOLVED: '6', CLOSED: '7', CANCELLED: '8' },
    STATE_LABEL:  { '1': 'new', '2': 'in progress', '3': 'on hold', '6': 'resolved', '7': 'closed', '8': 'cancelled' },
    PRIORITY_LABEL: { '1': 'critical', '2': 'high', '3': 'moderate', '4': 'low', '5': 'planning' },

    PREF_TABLE:         'x_196061_netra_v1_user_pref',
    NOTIFICATION_TABLE: 'x_196061_netra_v1_notification',
    WATCHLIST_TABLE:    'x_196061_netra_v1_watchlist',

    initialize: function () {
        this.userSysId = gs.getUserID();
        this.userName  = gs.getUserName();
    },

    // ============================================================
    //  R8 - TICKET WRITE POLICY (full control, kill-switch retained)
    //  Netra can create, edit and modify every ticket type. Writes
    //  are ON by default; setting <scope>.ticket_writes to exactly
    //  'false' is an emergency kill-switch that refuses create and
    //  mutate operations on this legacy scripted-REST /command path
    //  (the widget server enforces the same switch for Gemini tools).
    // ============================================================
    _ticketWritesEnabled: function () {
        return gs.getProperty('x_196061_netra_v1.ticket_writes', 'true') !== 'false';
    },

    READ_ONLY_MSG: 'Ticket writes are temporarily disabled by the administrator. I can still pull up everything about existing tickets: status, summaries, history, or keep watch on one for you.',

    // ============================================================
    //  Incident operations
    // ============================================================
    createTicket: function (description, urgency) {
        if (!this._ticketWritesEnabled())
            return { ok: false, read_only: true, error: 'Ticket writes are disabled.', message: this.READ_ONLY_MSG };
        if (!description || String(description).trim().length < 3)
            return { ok: false, error: 'I need a short description of the issue first.' };
        var gr = new GlideRecord('incident');
        gr.initialize();
        gr.short_description = String(description).trim();
        gr.urgency = String(urgency || '3');
        gr.caller_id = this.userSysId;
        gr.opened_by = this.userSysId;
        gr.contact_type = 'virtual_agent';
        var sid = gr.insert();
        if (!sid) return { ok: false, error: 'The platform refused the insert.' };
        gr.get(sid);
        return { ok: true, number: String(gr.number), sys_id: sid };
    },

    listMyTickets: function (limit) {
        // the user's plate: tickets they raised AND tickets assigned to them -
        // for IT staff the second is most of the work
        var gr = new GlideRecordSecure('incident');
        gr.addQuery('caller_id', this.userSysId).addOrCondition('assigned_to', this.userSysId);
        gr.addQuery('state', 'NOT IN', this.STATE.CLOSED + ',' + this.STATE.CANCELLED);
        gr.orderByDesc('sys_updated_on');
        gr.setLimit(limit || 10);
        gr.query();
        var out = [];
        while (gr.next()) out.push(this._shape(gr));
        var total = out.length, resolved = 0, assigned = 0;
        try {
            var ga = new GlideAggregate('incident');
            ga.addQuery('caller_id', this.userSysId).addOrCondition('assigned_to', this.userSysId);
            ga.addQuery('state', 'NOT IN', this.STATE.CLOSED + ',' + this.STATE.CANCELLED);
            ga.addAggregate('COUNT');
            ga.groupBy('state');
            ga.query();
            total = 0;
            while (ga.next()) {
                var c = parseInt(ga.getAggregate('COUNT'), 10) || 0;
                total += c;
                if (String(ga.getValue('state')) === this.STATE.RESOLVED) resolved += c;
            }
            var gb = new GlideAggregate('incident');
            gb.addQuery('assigned_to', this.userSysId);
            gb.addQuery('state', 'NOT IN', this.STATE.RESOLVED + ',' + this.STATE.CLOSED + ',' + this.STATE.CANCELLED);
            gb.addAggregate('COUNT');
            gb.query();
            assigned = gb.next() ? (parseInt(gb.getAggregate('COUNT'), 10) || 0) : 0;
        } catch (eA) {}
        return { ok: true, tickets: out, total: total, open_total: total - resolved, resolved_total: resolved,
                 assigned_open: assigned, raised_open: Math.max(0, total - resolved - assigned) };
    },

    resolveTicket: function (number, closeNotes) {
        if (!this._ticketWritesEnabled())
            return { ok: false, read_only: true, error: 'Ticket modification is disabled.', message: this.READ_ONLY_MSG };
        var gr = this._findByNumber(number);
        if (!gr) return { ok: false, error: 'Ticket ' + number + ' was not found, or you can not see it.' };
        if (!gr.canWrite()) return { ok: false, error: 'You do not have permission to resolve ' + number + '.' };
        var st = String(gr.getValue('state') || '');
        // re-resolving would overwrite someone's close notes and could not be undone honestly
        if (st === this.STATE.RESOLVED || st === this.STATE.CLOSED || st === this.STATE.CANCELLED) {
            return { ok: false, already: true, error: number + ' is already ' + this.STATE_LABEL[st] + ' - I changed nothing.' };
        }
        var before = { state: st, close_code: String(gr.getValue('close_code') || ''), close_notes: String(gr.getValue('close_notes') || '') };
        gr.setValue('state', this.STATE.RESOLVED);
        gr.setValue('close_code', 'Solved (Permanently)');
        if (closeNotes) gr.setValue('close_notes', closeNotes);
        else if (!gr.getValue('close_notes')) gr.setValue('close_notes', 'Resolved via Netra.');
        gr.setValue('resolved_by', this.userSysId);
        gr.resolved_at = new GlideDateTime();
        if (!gr.update()) return { ok: false, error: 'The platform refused to resolve ' + number + '.' };
        var chk = this._findByNumber(number);
        if (!chk || String(chk.getValue('state')) !== this.STATE.RESOLVED) {
            return { ok: false, error: 'I asked to resolve ' + number + ' but it is still ' + (chk ? this.STATE_LABEL[String(chk.getValue('state'))] || 'unchanged' : 'unchanged') + ' - a rule on the platform may need more fields.' };
        }
        return { ok: true, verified: true, number: number, before: before, message: number + ' is resolved - I read it back.' };
    },

    updateTicket: function (number, comment) {
        if (!this._ticketWritesEnabled())
            return { ok: false, read_only: true, error: 'Ticket modification is disabled.', message: this.READ_ONLY_MSG };
        if (!comment || comment.trim().length < 1) return { ok: false, error: 'Comment is empty.' };
        var gr = this._findByNumber(number);
        if (!gr) return { ok: false, error: 'Ticket ' + number + ' was not found, or you can not see it.' };
        if (!gr.canWrite()) return { ok: false, error: 'You do not have permission to comment on ' + number + '.' };
        gr.comments = comment;
        if (!gr.update()) return { ok: false, error: 'The platform refused the comment on ' + number + '.' };
        return { ok: true, number: number, message: 'Comment added to ' + number + ' - the caller can see it.' };
    },

    getStatus: function (number) {
        var gr = this._findByNumber(number);
        if (!gr) return { ok: false, error: 'Ticket ' + number + ' was not found, or you can not see it.' };
        return { ok: true, ticket: this._shape(gr) };
    },

    /** Search the user's incidents by keyword in short_description / description. */
    searchTickets: function (keyword, limit) {
        var q = String(keyword || '').trim();
        if (q.length < 2) return { ok: false, error: 'Please give me a longer search term.' };
        var gr = new GlideRecord('incident');
        gr.addQuery('caller_id', this.userSysId)
          .addOrCondition('assigned_to', this.userSysId);
        gr.addQuery('short_descriptionLIKE' + q + '^ORdescriptionLIKE' + q);
        gr.orderByDesc('sys_updated_on');
        gr.setLimit(limit || 5);
        gr.query();
        var out = [];
        while (gr.next()) out.push(this._shape(gr));
        return { ok: true, tickets: out, query: q };
    },

    /** Full record + recent comments for read-aloud. */
    readTicket: function (number) {
        var gr = this._findByNumberAny(number);
        if (!gr) return { ok: false, error: 'Ticket ' + number + ' not found.' };
        var shaped = this._shape(gr);
        shaped.description = String(gr.description || '');
        shaped.recent_comments = this._recentJournal(gr, 5);
        return { ok: true, ticket: shaped };
    },

    // ============================================================
    //  Approvals
    // ============================================================
    listPendingApprovals: function () {
        var gr = new GlideRecord('sysapproval_approver');
        gr.addQuery('approver', this.userSysId);
        gr.addQuery('state', 'requested');
        gr.orderByDesc('sys_created_on');
        gr.setLimit(10);
        gr.query();
        var out = [];
        while (gr.next()) {
            var subject = '';
            var ref = '';
            // Avoid getRefRecord() - fenced in some scoped contexts.
            // Use Document-ID pattern: sysapproval = sys_id, source_table = table name.
            try {
                var srcSysId = String(gr.sysapproval || '');
                var srcTable = String(gr.source_table || gr.sysapproval_table || '');
                if (srcSysId && srcTable) {
                    var srcRec = new GlideRecord(srcTable);
                    if (srcRec.isValid() && srcRec.get(srcSysId)) {
                        ref = String(srcRec.getValue('number') || '');
                        subject = ref + ' - ' + String(srcRec.getValue('short_description') || '');
                    }
                }
            } catch (e) {}
            out.push({
                sys_id:  String(gr.sys_id),
                subject: subject,
                ref_number: ref,
                created: gr.getDisplayValue('sys_created_on')
            });
        }
        var total = out.length;
        try {
            var ga = new GlideAggregate('sysapproval_approver');
            ga.addQuery('approver', this.userSysId);
            ga.addQuery('state', 'requested');
            ga.addAggregate('COUNT');
            ga.query();
            if (ga.next()) total = parseInt(ga.getAggregate('COUNT'), 10) || total;
        } catch (eA) {}
        return { ok: true, approvals: out, total: total };
    },

    /** the user's pending approval for a record number, with what it is about */
    findPendingApproval: function (refNumber) {
        if (!refNumber) return { ok: false, error: 'Which one should I act on?' };
        var gr = new GlideRecord('sysapproval_approver');
        gr.addQuery('approver', this.userSysId);
        gr.addQuery('state', 'requested');
        gr.query();
        while (gr.next()) {
            try {
                var srcSysId = String(gr.sysapproval || '');
                var srcTable = String(gr.source_table || gr.sysapproval_table || '');
                if (!srcSysId || !srcTable) continue;
                var srcRec = new GlideRecord(srcTable);
                if (!srcRec.isValid() || !srcRec.get(srcSysId)) continue;
                if (String(srcRec.getValue('number') || '').toUpperCase() === String(refNumber).toUpperCase()) {
                    return { ok: true, approval_sys_id: String(gr.sys_id), number: String(srcRec.getValue('number')),
                             subject: String(srcRec.getValue('short_description') || '').substring(0, 160) };
                }
            } catch (e) {}
        }
        return { ok: false, error: 'I could not find a pending approval of yours for ' + refNumber + '.' };
    },

    decideApproval: function (refNumber, approve) {
        var found = this.findPendingApproval(refNumber);
        if (!found.ok) return found;
        var gr = new GlideRecord('sysapproval_approver');
        if (!gr.get(found.approval_sys_id)) return { ok: false, error: 'That approval is gone.' };
        gr.state = approve ? 'approved' : 'rejected';
        gr.comments = approve ? 'Approved via Netra.' : 'Rejected via Netra.';
        if (!gr.update()) return { ok: false, error: 'The platform refused the decision on ' + refNumber + '.' };
        var chk = new GlideRecord('sysapproval_approver');
        var want = approve ? 'approved' : 'rejected';
        if (!chk.get(found.approval_sys_id) || String(chk.getValue('state')) !== want) {
            return { ok: false, error: 'I recorded the decision on ' + refNumber + ' but it did not stick when I read it back.' };
        }
        return { ok: true, verified: true, number: refNumber, decision: want,
                 message: refNumber + ' is ' + want + ' - I read it back. Decisions can not be undone.' };
    },

    // ============================================================
    //  Watchlist
    // ============================================================
    addWatch: function (table, sysId, number) {
        var w = new GlideRecord(this.WATCHLIST_TABLE);
        w.addQuery('user', this.userSysId);
        w.addQuery('record_table', table);
        w.addQuery('record_sys_id', sysId);
        w.setLimit(1);
        w.query();
        if (w.next()) return { ok: true, already: true, number: number };
        w.initialize();
        w.user = this.userSysId;
        w.record_table = table;
        w.record_sys_id = sysId;
        w.record_number = number || '';
        w.insert();
        return { ok: true, number: number };
    },

    removeWatch: function (table, sysId) {
        var w = new GlideRecord(this.WATCHLIST_TABLE);
        w.addQuery('user', this.userSysId);
        w.addQuery('record_table', table);
        w.addQuery('record_sys_id', sysId);
        w.deleteMultiple();
        return { ok: true };
    },

    listWatched: function () {
        var w = new GlideRecord(this.WATCHLIST_TABLE);
        w.addQuery('user', this.userSysId);
        w.orderByDesc('sys_created_on');
        w.setLimit(20);
        w.query();
        var out = [];
        while (w.next()) out.push({
            table:  String(w.record_table),
            sys_id: String(w.record_sys_id),
            number: String(w.record_number)
        });
        return { ok: true, watched: out };
    },

    // ============================================================
    //  User preferences (pause / resume / voice mode)
    // ============================================================
    pauseNotifications: function (hours) {
        if (!hours || hours <= 0) return { ok: false, error: 'Invalid pause duration.' };
        var pref = this._getOrCreatePref();
        var until = new GlideDateTime();
        until.add(Math.round(hours * 3600 * 1000));
        pref.paused_until = until;
        pref.update();
        return { ok: true, paused_until_local: until.getDisplayValue(), hours: hours,
                 message: 'Notifications paused for ' + hours + ' hour' + (hours === 1 ? '' : 's') + '.' };
    },

    resumeNotifications: function () {
        var pref = this._getOrCreatePref();
        pref.paused_until = '';
        pref.update();
        return { ok: true };
    },

    isPaused: function () {
        var pref = this._getOrCreatePref(true);
        if (!pref) return false;
        var until = pref.paused_until;
        if (!until || String(until) === '') return false;
        return new GlideDateTime(String(until)).compareTo(new GlideDateTime()) > 0;
    },

    setVoiceMode: function (mode) {
        var pref = this._getOrCreatePref();
        pref.voice_mode = String(mode || 'normal').toLowerCase();
        pref.update();
        return { ok: true, mode: pref.voice_mode };
    },

    _getOrCreatePref: function (readOnly) {
        var gr = new GlideRecord(this.PREF_TABLE);
        gr.addQuery('user', this.userSysId);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) return gr;
        if (readOnly) return null;
        gr.initialize();
        gr.user = this.userSysId;
        gr.watch_assignments = true;
        gr.watch_comments = true;
        gr.watch_approvals = true;
        gr.voice_mode = 'normal';
        gr.insert();
        gr.get(gr.sys_id);
        return gr;
    },

    // ============================================================
    //  Helpers
    // ============================================================
    // GlideRecordSecure: Netra sees and changes exactly what the signed-in
    // user may - the same ACLs as the incident form (a technician can work
    // their group's tickets; a caller only their own)
    _findByNumber: function (number) {
        if (!number) return null;
        var gr = new GlideRecordSecure('incident');
        gr.addQuery('number', String(number).toUpperCase());
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr : null;
    },

    _findByNumberAny: function (number) {
        return this._findByNumber(number);
    },

    // only the journals the user may read: a caller never hears work notes
    _recentJournal: function (gr, limit) {
        // under GlideRecordSecure an unreadable field is null and not "valid"
        var can = function (f) { try { var el = gr.isValidField(f) ? gr.getElement(f) : null; return !!(el && el.canRead()); } catch (e) { return false; } };
        var els = [];
        if (can('comments')) els.push('comments');
        if (can('work_notes')) els.push('work_notes');
        if (!els.length) return [];
        var j = new GlideRecord('sys_journal_field');
        j.addQuery('element_id', String(gr.sys_id));
        j.addQuery('element', 'IN', els.join(','));
        j.orderByDesc('sys_created_on');
        j.setLimit(limit || 5);
        j.query();
        var out = [];
        while (j.next()) out.push({
            element: String(j.element),
            author:  String(j.sys_created_by),
            body:    String(j.value || '').replace(/\s+/g, ' ').trim(),
            created: String(j.sys_created_on)
        });
        return out;
    },

    _shape: function (gr) {
        var state = String(gr.state || '');
        var prio  = String(gr.priority || '');
        return {
            number: String(gr.number),
            sys_id: String(gr.sys_id),
            short_description: String(gr.short_description),
            state: this.STATE_LABEL[state] || state,
            priority: this.PRIORITY_LABEL[prio] || prio,
            assigned_to: gr.assigned_to.getDisplayValue() || null,
            // the user's own timezone and format, never raw UTC the model would misread
            updated: gr.getDisplayValue('sys_updated_on'),
            created: gr.getDisplayValue('sys_created_on'),
            role: String(gr.getValue('assigned_to') || '') === this.userSysId ? 'assigned to you' : 'raised by you'
        };
    },

    type: 'NetraTools'
};
